mapper.select:
SELECT M.SQL_SEQ, M.CPNY_ID, NVL(M.PGM_NM, 'PAY') AS PGM_NM, M.SQL_NM, M.SQL_FROM_STMT, M.SQL_ORDER_BY_ID, M.SQL_DESC, NVL(M.SQL_STAT, 'N') AS SQL_STAT, NVL(M.IS_SPECIAL, 'N') AS IS_SPECIAL, TO_CHAR(M.RGST_DTIME, 'DD/MM/YYYY HH24:MI') AS RGST_DTIME, TO_CHAR(M.UPDT_DTIME, 'DD/MM/YYYY HH24:MI') AS UPDT_DTIME, M.UPDT_USER FROM SYS_SQL_MASTER M WHERE
AND M.PGM_NM = #{pgmNm, jdbcType=VARCHAR}
AND M.SQL_SEQ = #{sqlSeq, jdbcType=VARCHAR}
AND UPPER(M.SQL_NM) LIKE '%' || UPPER(#{sqlNm, jdbcType=VARCHAR}) || '%'
ORDER BY TO_NUMBER(M.SQL_SEQ)

mapper.delete:
DELETE FROM SYS_SQL_MASTER M
 WHERE M.SQL_SEQ = #{sqlSeq, jdbcType=VARCHAR}
   AND

mapper.select:
SELECT P.SQL_SEQ, P.SQL_PARAM_NO, P.PARAM, P.EN_SQL_PARAM_DESC, P.CN_SQL_PARAM_DESC, P.SQL_PARAM_TP, P.DEFAULT_VAL, P.SORT_CD, P.USE_YN FROM SYS_PARAM_BY_SQL P WHERE P.SQL_SEQ = #{sqlSeq, jdbcType=VARCHAR}
AND P.USE_YN = 'Y'
ORDER BY TO_NUMBER(REGEXP_SUBSTR(P.SORT_CD, '^\d+$')) NULLS LAST, TO_NUMBER(P.SQL_PARAM_NO)

mapper.update:
UPDATE SYS_PARAM_BY_SQL
   SET USE_YN = 'N'
 WHERE SQL_SEQ = #{sqlSeq, jdbcType=VARCHAR}

UPDATE SYS_PARAM_BY_SQL
   SET USE_YN = 'Y'

     , EN_SQL_PARAM_DESC = #{enSqlParamDesc, jdbcType=VARCHAR}
     , CN_SQL_PARAM_DESC = #{cnSqlParamDesc, jdbcType=VARCHAR}
     , SQL_PARAM_TP      = #{sqlParamTp, jdbcType=VARCHAR}
     , SORT_CD           = #{sortCd, jdbcType=VARCHAR}

 WHERE SQL_SEQ = #{sqlSeq, jdbcType=VARCHAR}
   AND PARAM = #{param, jdbcType=VARCHAR}
